# 3. Obtener la estrategia mediante Factory
estrategia_pago = self.fabrica_pagos.obtener(tipo_pago)

# 4. Procesar el pago con reintentos
intento = 0
transaccion_id = None

while intento < max_reintentos:
    try:
        transaccion_id = estrategia_pago.procesar_pago(
            monto,
            token_tarjeta
        )
        break

    except ConnectionError as e:
        intento += 1

        if intento >= max_reintentos:
            self.inventario.liberar_stock(
                producto_id,
                cantidad
            )

            raise RuntimeError(
                f"Error de red tras "
                f"{max_reintentos} reintentos: {str(e)}"
            ) from e

    except ValueError:
        self.inventario.liberar_stock(
            producto_id,
            cantidad
        )
        raise

args.despues:
# 3. Verificar idempotencia por pedido antes de cobrar
conn = self._get_connection()
fila_existente = conn.execute(
    "SELECT estado, transaccion_id FROM pedidos WHERE id = ?",
    (pedido_id,)
).fetchone()
if not self.conn:
    conn.close()

if fila_existente is not None:
    estado_actual, tx_existente = fila_existente
    if estado_actual == "PAGADO":
        self.inventario.liberar_stock(producto_id, cantidad)
        return {
            "pedido_id": pedido_id,
            "estado": "PAGADO",
            "transaccion_id": tx_existente
        }
    raise RuntimeError(
        f"El pedido {pedido_id} ya tiene un intento de cobro registrado ({estado_actual})."
    )

# 4. Obtener la estrategia mediante Factory
estrategia_pago = self.fabrica_pagos.obtener(tipo_pago)

# 5. Procesar el pago de forma idempotente (sin reintentar tras ConnectionError)
try:
    transaccion_id = estrategia_pago.procesar_pago(
        monto,
        token_tarjeta
    )
except ConnectionError as e:
    conn = self._get_connection()
    conn.execute(
        "INSERT INTO pedidos VALUES (?, ?, ?, ?, ?, ?)",
        (pedido_id, producto_id, cantidad, monto, "PENDIENTE_VERIFICACION", None)
    )
    conn.commit()
    if not self.conn:
        conn.close()

    self.inventario.liberar_stock(
        producto_id,
        cantidad
    )
    raise RuntimeError(
        f"Error de red al procesar el pago del pedido {pedido_id}; "
        f"no se reintenta para evitar cobros duplicados: {str(e)}"
    ) from e
except ValueError:
    self.inventario.liberar_stock(
        producto_id,
        cantidad
    )
    raise
